import { Controller, Get, Post, Put, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 신규 등록 시 사용 여부 초기값
const INITIAL_USE_STATUS = '사용';
const ROLE = '예산·회계 담당자';
const BUSINESS_TYPES = ['고유목적사업', '수익사업', '공통사업'];
const PROJECT_TYPES = ['공통', '직접사업'];
const DATE_PATTERN = /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/;
const ID_PATTERN = /^[0-9]+$/;
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

type Body = Record<string, unknown>;

interface Db {
  query: (sql: string, params?: Body) => Promise<Body[]>;
  execute: (sql: string, params?: Body) => Promise<number>;
}

interface ProjectInput {
  projectCode: string;
  projectName: string;
  projectShortName: string | null;
  managingAccount: string | null;
  startDate: string;
  endDate: string;
  businessType: string;
  projectType: string;
  departmentId: string;
  managerId: string;
  amount: string | null;
  purpose: string | null;
  content: string | null;
  employeeIds: string[];
}

function periodError(): ApiError {
  return new ApiError(422, 'PROJECT_PERIOD_INVALID', '필수 값이 없거나 종료일이 시작일보다 빠릅니다.');
}

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function textOf(value: unknown): string | null {
  if (typeof value === 'string' && value.trim() !== '') {
    return value.trim();
  }
  return null;
}

function requiredText(value: unknown, max: number, label: string): string {
  const text = textOf(value);
  if (text === null) {
    throw periodError();
  }
  if (text.length > max) {
    throw invalid(label + '이(가) 너무 깁니다.');
  }
  return text;
}

function optionalText(value: unknown, max: number, label: string): string | null {
  const text = textOf(value);
  if (text !== null && text.length > max) {
    throw invalid(label + '이(가) 너무 깁니다.');
  }
  return text;
}

function idOf(value: unknown): string | null {
  if (typeof value === 'number' && Number.isInteger(value) && value > 0) {
    return String(value);
  }
  if (typeof value === 'string' && ID_PATTERN.test(value.trim()) && Number(value) > 0) {
    return value.trim();
  }
  return null;
}

function requiredId(value: unknown, label: string): string {
  if (value === undefined || value === null || value === '') {
    throw periodError();
  }
  const id = idOf(value);
  if (id === null) {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  return id;
}

function requiredDate(value: unknown, label: string): string {
  const text = textOf(value);
  if (text === null) {
    throw periodError();
  }
  if (!DATE_PATTERN.test(text)) {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  return text;
}

function amountOf(value: unknown): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  const n = typeof value === 'number' ? value : typeof value === 'string' ? Number(value) : NaN;
  if (!Number.isFinite(n) || n < 0) {
    throw invalid('프로젝트 금액은 0 이상의 숫자여야 합니다.');
  }
  return String(n);
}

function parseProject(data: Body): ProjectInput {
  const businessType = requiredText(data['businessType'], 20, '사업 구분');
  const projectType = requiredText(data['projectType'], 20, '프로젝트 유형');
  if (!BUSINESS_TYPES.includes(businessType)) {
    throw invalid('사업 구분은 고유목적사업, 수익사업, 공통사업 중 하나여야 합니다.');
  }
  if (!PROJECT_TYPES.includes(projectType)) {
    throw invalid('프로젝트 유형은 공통, 직접사업 중 하나여야 합니다.');
  }
  const rawIds = data['permittedEmployeeIds'];
  const employeeIds: string[] = [];
  if (rawIds !== undefined && rawIds !== null) {
    if (!Array.isArray(rawIds)) {
      throw invalid('사용 권한 대상 임직원 ID 목록 형식이 올바르지 않습니다.');
    }
    for (const raw of rawIds) {
      const id = idOf(raw);
      if (id === null) {
        throw invalid('사용 권한 대상 임직원 ID가 올바르지 않습니다.');
      }
      if (!employeeIds.includes(id)) {
        employeeIds.push(id);
      }
    }
  }
  return {
    projectCode: requiredText(data['projectCode'], 30, '프로젝트 코드'),
    projectName: requiredText(data['projectName'], 200, '프로젝트 명칭'),
    projectShortName: optionalText(data['projectShortName'], 100, '프로젝트 약칭'),
    managingAccount: optionalText(data['managingAccount'], 50, '관리계좌'),
    startDate: requiredDate(data['startDate'], '시작일'),
    endDate: requiredDate(data['endDate'], '종료일'),
    businessType,
    projectType,
    departmentId: requiredId(data['departmentId'], '주관부서 ID'),
    managerId: requiredId(data['managerId'], '담당자 ID'),
    amount: amountOf(data['amount']),
    purpose: optionalText(data['purpose'], 100000, '프로젝트 목적'),
    content: optionalText(data['content'], 100000, '프로젝트 내용'),
    employeeIds,
  };
}

function pageNumber(value: unknown, fallback: number, label: string): number {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }
  const n = Number(value);
  if (!Number.isInteger(n) || n < 0) {
    throw invalid(label + ' 값이 올바르지 않습니다.');
  }
  return n;
}

async function checkPeriod(db: Db, input: ProjectInput): Promise<void> {
  const rows = await db.query(
    'SELECT CAST(:endDate AS date) < CAST(:startDate AS date) AS "invalid"',
    { startDate: input.startDate, endDate: input.endDate },
  );
  if (rows[0]?.['invalid'] === true) {
    throw periodError();
  }
}

async function checkDuplicate(db: Db, code: string, projectId: string): Promise<void> {
  const rows = await db.query(
    'SELECT project_id FROM project WHERE project_code = :code AND project_id <> CAST(:projectId AS bigint)',
    { code, projectId },
  );
  if (rows.length > 0) {
    throw new ApiError(409, 'PROJECT_CODE_DUPLICATED', '이미 사용 중인 프로젝트 코드입니다.');
  }
}

async function checkReferences(db: Db, input: ProjectInput): Promise<void> {
  const departments = await db.query(
    'SELECT department_id FROM department WHERE department_id = CAST(:id AS bigint)',
    { id: input.departmentId },
  );
  if (departments.length === 0) {
    throw invalid('주관부서를 찾을 수 없습니다.');
  }
  const managers = await db.query(
    'SELECT employee_id FROM employee WHERE employee_id = CAST(:id AS bigint)',
    { id: input.managerId },
  );
  if (managers.length === 0) {
    throw invalid('담당자를 찾을 수 없습니다.');
  }
  for (const id of input.employeeIds) {
    const rows = await db.query(
      'SELECT employee_id FROM employee WHERE employee_id = CAST(:id AS bigint)',
      { id },
    );
    if (rows.length === 0) {
      throw invalid('사용 권한 대상 임직원을 찾을 수 없습니다.');
    }
  }
}

async function snapshot(db: Db, projectId: string): Promise<string | null> {
  const rows = await db.query(
    'SELECT row_to_json(p)::text AS "content" FROM project p WHERE p.project_id = CAST(:projectId AS bigint)',
    { projectId },
  );
  if (rows.length === 0) {
    return null;
  }
  return String(rows[0]['content']);
}

async function savePermissions(db: Db, projectId: string, employeeIds: string[]): Promise<void> {
  await db.execute(
    'DELETE FROM project_permission WHERE project_id = CAST(:projectId AS bigint) AND sub_project_id IS NULL',
    { projectId },
  );
  for (const employeeId of employeeIds) {
    await db.execute(
      `INSERT INTO project_permission (project_id, sub_project_id, employee_id, created_at, updated_at)
       VALUES (CAST(:projectId AS bigint), NULL, CAST(:employeeId AS bigint), now(), now())`,
      { projectId, employeeId },
    );
  }
}

async function recordHistory(
  db: Db,
  userId: string,
  changeType: string,
  projectId: string,
  before: string | null,
  after: string | null,
): Promise<void> {
  await db.execute(
    `INSERT INTO change_history
       (target_type, target_id, change_type, changed_at, changer_id, before_content, after_content, created_at, updated_at)
     VALUES
       ('project', CAST(:projectId AS bigint), :changeType, now(), CAST(:userId AS bigint), :before, :after, now(), now())`,
    { projectId, changeType, userId, before, after },
  );
}

function projectParams(input: ProjectInput): Body {
  return {
    projectCode: input.projectCode,
    projectName: input.projectName,
    projectShortName: input.projectShortName,
    managingAccount: input.managingAccount,
    startDate: input.startDate,
    endDate: input.endDate,
    businessType: input.businessType,
    projectType: input.projectType,
    departmentId: input.departmentId,
    managerId: input.managerId,
    amount: input.amount,
    purpose: input.purpose,
    content: input.content,
  };
}

@Controller('api/v1')
export class FnSfr00201Controller {
  @Post('/projects')
  @HttpCode(200)
  async createProject(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const input = parseProject(data);
    return transaction(async (db) => {
      await checkPeriod(db, input);
      await checkDuplicate(db, input.projectCode, '0');
      await checkReferences(db, input);
      const rows = await db.query(
        `INSERT INTO project
           (project_code, project_name, project_short_name, managing_account, business_type, project_type,
            start_date, end_date, department_id, manager_id, amount, purpose, content, use_status, created_at, updated_at)
         VALUES
           (:projectCode, :projectName, :projectShortName, :managingAccount, :businessType, :projectType,
            CAST(:startDate AS date), CAST(:endDate AS date), CAST(:departmentId AS bigint), CAST(:managerId AS bigint),
            CAST(:amount AS numeric), :purpose, :content, :useStatus, now(), now())
         RETURNING project_id AS "projectId"`,
        { ...projectParams(input), useStatus: INITIAL_USE_STATUS },
      );
      const projectId = String(rows[0]['projectId']);
      await savePermissions(db, projectId, input.employeeIds);
      const after = await snapshot(db, projectId);
      await recordHistory(db, user.id, '등록', projectId, null, after);
      return { projectId: Number(projectId) };
    });
  }

  @Put('/projects/:projectId')
  async updateProject(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const projectId = idOf(req.params['projectId']);
    if (projectId === null) {
      throw invalid('프로젝트 ID가 올바르지 않습니다.');
    }
    const data = checks.inputOf(req.body);
    const input = parseProject(data);
    return transaction(async (db) => {
      const before = await snapshot(db, projectId);
      if (before === null) {
        throw new ApiError(404, 'PROJECT_NOT_FOUND', '프로젝트를 찾을 수 없습니다.');
      }
      await checkPeriod(db, input);
      await checkDuplicate(db, input.projectCode, projectId);
      await checkReferences(db, input);
      await db.execute(
        `UPDATE project SET
           project_code = :projectCode,
           project_name = :projectName,
           project_short_name = :projectShortName,
           managing_account = :managingAccount,
           business_type = :businessType,
           project_type = :projectType,
           start_date = CAST(:startDate AS date),
           end_date = CAST(:endDate AS date),
           department_id = CAST(:departmentId AS bigint),
           manager_id = CAST(:managerId AS bigint),
           amount = CAST(:amount AS numeric),
           purpose = :purpose,
           content = :content,
           updated_at = now()
         WHERE project_id = CAST(:projectId AS bigint)`,
        { ...projectParams(input), projectId },
      );
      await savePermissions(db, projectId, input.employeeIds);
      const after = await snapshot(db, projectId);
      await recordHistory(db, user.id, '수정', projectId, before, after);
      return { projectId: Number(projectId) };
    });
  }

  @Delete('/projects/:projectId')
  async deleteProject(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const projectId = idOf(req.params['projectId']);
    if (projectId === null) {
      throw invalid('프로젝트 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const before = await snapshot(db, projectId);
      if (before === null) {
        throw new ApiError(404, 'PROJECT_NOT_FOUND', '프로젝트를 찾을 수 없습니다.');
      }
      // 가정: 스펙에 확인되는 사용 이력은 하위사업 등록뿐이다 (사용 권한 설정은 이력으로 보지 않는다)
      const used = await db.query(
        'SELECT sub_project_id FROM sub_project WHERE project_id = CAST(:projectId AS bigint)',
        { projectId },
      );
      if (used.length > 0) {
        throw new ApiError(409, 'PROJECT_IN_USE', '사용 이력이 있는 프로젝트는 삭제할 수 없습니다.');
      }
      await db.execute(
        'DELETE FROM project_permission WHERE project_id = CAST(:projectId AS bigint)',
        { projectId },
      );
      await db.execute(
        'DELETE FROM project WHERE project_id = CAST(:projectId AS bigint)',
        { projectId },
      );
      await recordHistory(db, user.id, '삭제', projectId, before, null);
      return {};
    });
  }

  @Get('/projects')
  async listProjects(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const page = pageNumber(query['page'], 0, '쪽 번호');
    const size = pageNumber(query['size'], DEFAULT_SIZE, '쪽 크기');
    if (size < 1 || size > MAX_SIZE) {
      throw invalid('쪽 크기는 1 이상 200 이하여야 합니다.');
    }
    const projectName = textOf(query['projectName']);
    const businessType = textOf(query['businessType']);
    if (businessType !== null && !BUSINESS_TYPES.includes(businessType)) {
      throw invalid('사업 구분 값이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const where = `WHERE (CAST(:projectName AS text) IS NULL OR project_name LIKE '%' || CAST(:projectName AS text) || '%')
         AND (CAST(:businessType AS text) IS NULL OR business_type = CAST(:businessType AS text))`;
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM project ' + where,
        { projectName, businessType },
      );
      const items = await db.query(
        `SELECT project_id AS "projectId",
                project_code AS "projectCode",
                project_name AS "projectName",
                business_type AS "businessType",
                project_type AS "projectType",
                to_char(start_date, 'YYYY-MM-DD') AS "startDate",
                to_char(end_date, 'YYYY-MM-DD') AS "endDate",
                amount AS "amount"
         FROM project
         ` + where + `
         ORDER BY project_id DESC
         LIMIT :size OFFSET :offset`,
        { projectName, businessType, size, offset: page * size },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }
}

