import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Form,
  Field,
  TextInput,
  NumberInput,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  Tiles,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const BUSINESS_OPTIONS: [string, string][] = [
  ['고유목적사업', '고유목적사업'],
  ['수익사업', '수익사업'],
  ['공통사업', '공통사업'],
];
const TYPE_OPTIONS: [string, string][] = [
  ['공통', '공통'],
  ['직접사업', '직접사업'],
];
const PAGE_SIZE = 20;

type Mode =
  | null
  | { kind: 'create' }
  | { kind: 'edit'; row: Row }
  | { kind: 'delete'; row: Row };

function dayOf(value: unknown): string {
  return value ? String(value).slice(0, 10) : '';
}

function blank(value: unknown): boolean {
  return value === undefined || value === null || value === '';
}

interface ProjectFormProps {
  role: string;
  initial: Row;
  projectId?: number;
  onDone: (message: string) => void;
}

function ProjectForm({ role, initial, projectId, onDone }: ProjectFormProps) {
  const [form, setForm] = useState<Row>(initial);
  const [ids, setIds] = useState<number[]>([]);
  const [picked, setPicked] = useState<number | string>('');

  const set = (key: string, value: unknown) => setForm({ ...form, [key]: value });

  const addId = (value: number | string) => {
    setPicked('');
    if (typeof value === 'number' && !ids.includes(value)) {
      setIds([...ids, value]);
    }
  };

  const submit = async () => {
    const required: [string, string][] = [
      ['projectCode', '프로젝트 코드'],
      ['projectName', '프로젝트 명칭'],
      ['startDate', '시작일'],
      ['endDate', '종료일'],
      ['businessType', '사업 구분'],
      ['projectType', '프로젝트 유형'],
      ['departmentId', '주관부서'],
      ['managerId', '담당자'],
    ];
    for (const [key, label] of required) {
      if (blank(form[key])) {
        throw new Error(label + '을(를) 입력하세요.');
      }
    }
    if (String(form.endDate) < String(form.startDate)) {
      throw new Error('종료일은 시작일보다 빠를 수 없습니다.');
    }
    const body: Row = {
      projectCode: form.projectCode,
      projectName: form.projectName,
      projectShortName: form.projectShortName,
      managingAccount: form.managingAccount,
      startDate: form.startDate,
      endDate: form.endDate,
      businessType: form.businessType,
      projectType: form.projectType,
      departmentId: form.departmentId,
      managerId: form.managerId,
      purpose: form.purpose,
      content: form.content,
      permittedEmployeeIds: ids,
    };
    if (!blank(form.amount)) {
      body.amount = form.amount;
    }
    if (projectId === undefined) {
      await call('POST', '/projects', role, body);
      onDone('프로젝트를 등록했습니다.');
    } else {
      await call('PUT', '/projects/' + projectId, role, body);
      onDone('프로젝트를 수정했습니다.');
    }
  };

  const note = projectId === undefined
    ? undefined
    : '목록에 없는 항목(주관부서·담당자·목적·내용·사용 권한)은 다시 입력해야 합니다.';

  return (
    <Form onSubmit={submit} submit={projectId === undefined ? '등록' : '수정'} note={note}>
      <Field label="프로젝트 코드" required>
        <TextInput value={form.projectCode} onChange={(v) => set('projectCode', v)} />
      </Field>
      <Field label="프로젝트 명칭" required>
        <TextInput value={form.projectName} onChange={(v) => set('projectName', v)} />
      </Field>
      <Field label="프로젝트 약칭">
        <TextInput value={form.projectShortName} onChange={(v) => set('projectShortName', v)} />
      </Field>
      <Field label="관리계좌">
        <TextInput value={form.managingAccount} onChange={(v) => set('managingAccount', v)} />
      </Field>
      <Field label="시작일" required>
        <DateInput value={form.startDate} onChange={(v) => set('startDate', v)} />
      </Field>
      <Field label="종료일" required>
        <DateInput value={form.endDate} onChange={(v) => set('endDate', v)} />
      </Field>
      <Field label="사업 구분" required>
        <Select
          value={form.businessType}
          onChange={(v) => set('businessType', v)}
          options={BUSINESS_OPTIONS}
        />
      </Field>
      <Field label="프로젝트 유형" required>
        <Select
          value={form.projectType}
          onChange={(v) => set('projectType', v)}
          options={TYPE_OPTIONS}
        />
      </Field>
      <Field label="주관부서" required>
        <LookupSelect
          table="department"
          role={role}
          value={form.departmentId}
          onChange={(v) => set('departmentId', v)}
        />
      </Field>
      <Field label="담당자" required>
        <LookupSelect
          table="employee"
          role={role}
          value={form.managerId}
          onChange={(v) => set('managerId', v)}
        />
      </Field>
      <Field label="프로젝트 금액">
        <NumberInput value={form.amount} onChange={(v) => set('amount', v)} />
      </Field>
      <Field label="프로젝트 목적" wide>
        <TextInput multiline value={form.purpose} onChange={(v) => set('purpose', v)} />
      </Field>
      <Field label="프로젝트 내용" wide>
        <TextInput multiline value={form.content} onChange={(v) => set('content', v)} />
      </Field>
      <Field label="사용 권한 대상 임직원" wide hint="설정하면 권한이 부여된 사용자만 프로젝트를 사용할 수 있습니다.">
        <LookupSelect
          table="employee"
          role={role}
          value={picked}
          onChange={addId}
          placeholder="임직원 추가"
        />
        <div>
          {ids.map((id) => (
            <span key={id}>
              <RefName table="employee" role={role} value={id} />
              <button type="button" onClick={() => setIds(ids.filter((x) => x !== id))}>
                제거
              </button>
            </span>
          ))}
        </div>
      </Field>
    </Form>
  );
}

export default function FnSfr00201Page({ role, notify }: PageProps) {
  const [nameInput, setNameInput] = useState('');
  const [typeInput, setTypeInput] = useState('');
  const [query, setQuery] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [mode, setMode] = useState<Mode>(null);

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/projects', role, undefined, { ...query, page, size: PAGE_SIZE }),
    [role, query, page],
  );

  const rows = data?.items ?? [];
  const pageAmount = rows.reduce((sum, r) => sum + (Number(r.amount) || 0), 0);

  const search = () => {
    setPage(0);
    setQuery({ projectName: nameInput, businessType: typeInput });
  };

  const reset = () => {
    setNameInput('');
    setTypeInput('');
    setPage(0);
    setQuery({});
  };

  const done = (message: string) => {
    setMode(null);
    notify(message);
    reload();
  };

  const remove = async (row: Row) => {
    await call('DELETE', '/projects/' + row.projectId, role);
    done('프로젝트를 삭제했습니다.');
  };

  const columns = [
    { key: 'projectCode', label: '프로젝트 코드' },
    { key: 'projectName', label: '프로젝트 명칭' },
    { key: 'businessType', label: '사업 구분', render: (r: Row) => <Badge value={r.businessType} /> },
    { key: 'projectType', label: '프로젝트 유형' },
    { key: 'startDate', label: '시작일', render: (r: Row) => <DateText value={r.startDate} /> },
    { key: 'endDate', label: '종료일', render: (r: Row) => <DateText value={r.endDate} /> },
    { key: 'amount', label: '프로젝트 금액', render: (r: Row) => <Num value={r.amount} /> },
    {
      key: 'actions',
      label: '처리',
      render: (r: Row) => (
        <span>
          <button type="button" onClick={() => setMode({ kind: 'edit', row: r })}>
            수정
          </button>
          <button type="button" onClick={() => setMode({ kind: 'delete', row: r })}>
            삭제
          </button>
        </span>
      ),
    },
  ];

  const editInitial = (row: Row): Row => ({
    projectCode: row.projectCode,
    projectName: row.projectName,
    startDate: dayOf(row.startDate),
    endDate: dayOf(row.endDate),
    businessType: row.businessType,
    projectType: row.projectType,
    amount: row.amount ?? '',
  });

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>프로젝트 현황</h2>
        <Tiles
          items={[
            ['전체 프로젝트', <Num value={data?.total ?? 0} />],
            ['현재 쪽 건수', <Num value={rows.length} />],
            ['현재 쪽 금액 합계', <Num value={pageAmount} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>프로젝트 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="프로젝트 명칭">
            <TextInput value={nameInput} onChange={setNameInput} />
          </Field>
          <Field label="사업 구분">
            <Select
              value={typeInput}
              onChange={setTypeInput}
              options={BUSINESS_OPTIONS}
              placeholder="전체"
            />
          </Field>
        </Filters>
        <Band total={data?.total}>
          <button type="button" onClick={() => setMode({ kind: 'create' })}>
            프로젝트 등록
          </button>
        </Band>
        {error ? <p>{error}</p> : null}
        <DataTable
          columns={columns}
          rows={rows}
          empty={loading ? '불러오는 중입니다.' : '프로젝트가 없습니다.'}
        />
        <Pager page={page} size={PAGE_SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>

      {mode?.kind === 'create' ? (
        <Drawer title="프로젝트 등록" onClose={() => setMode(null)}>
          <ProjectForm role={role} initial={{}} onDone={done} />
        </Drawer>
      ) : null}

      {mode?.kind === 'edit' ? (
        <Drawer title="프로젝트 수정" onClose={() => setMode(null)}>
          <ProjectForm
            role={role}
            initial={editInitial(mode.row)}
            projectId={Number(mode.row.projectId)}
            onDone={done}
          />
        </Drawer>
      ) : null}

      {mode?.kind === 'delete' ? (
        <Drawer title="프로젝트 삭제" onClose={() => setMode(null)}>
          <Form
            danger
            submit="삭제"
            onSubmit={() => remove(mode.row)}
            note={'프로젝트 "' + String(mode.row.projectName) + '"을(를) 삭제합니다. 사용 이력이 있으면 삭제할 수 없습니다.'}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
